struct string_rep { char* text; int capacity; int length; };
struct stringx {
  int pad;
  string_rep* rep;
  int compare(const stringx& b) const {
    int n = rep->length < b.rep->length ? rep->length : b.rep->length;
    for (int i = 0; i < n; ++i) {
      if (rep->text[i] < b.rep->text[i]) return -1;
      if (b.rep->text[i] < rep->text[i]) return 1;
    }
    if (rep->length < b.rep->length) return -1;
    if (b.rep->length < rep->length) return 1;
    return 0;
  }
  bool operator<(const stringx& b) const { return compare(b) == -1; }
};
struct rb_node { int color; rb_node* parent; rb_node* left; rb_node* right; stringx key; };
