iterator* target(iterator* out, tree* self, const stringx& k) {
  rb_node* y = self->header;
  rb_node* x = self->header->parent;
  while (x != 0)
    if (!(x->key < k)) y = x, x = x->left;
    else x = x->right;
  iterator j(y);
  iterator e(self->header);
  *out = (j.node == e.node || k < j.node->key) ? e : j;
  return out;
}
